// Trim spasi pada teks & pastikan kolom angka bertipe number (parseFloat)
const kolomAngka = ['Jumlah Stok', 'Penjualan Harian', 'Harga Satuan (IDR)', 'Total Penjualan (IDR)'];

const toNumber = (v) => {
  if (typeof v === 'number') return v;
  const bersih = String(v ?? '').replace(/[^0-9,.-]/g, '').replace(/\./g, '').replace(',', '.');
  const n = parseFloat(bersih);
  return isNaN(n) ? 0 : n;
};

return $input.all()
  .map((item) => {
    const hasil = {};
    for (const [key, value] of Object.entries(item.json)) {
      if (key === 'row_number') continue;
      const k = String(key).trim();
      hasil[k] = typeof value === 'string' ? value.trim() : value;
    }
    for (const k of kolomAngka) {
      if (k in hasil) hasil[k] = toNumber(hasil[k]);
    }
    return { json: hasil };
  })
  .filter((item) => item.json['ID Laporan']);

// Ubah struktur kolom Sheet 3 agar sama persis dengan format Master Sheet
return $input.all().map((item) => {
  const r = item.json;
  return {
    json: {
      'ID Laporan': r['ID Laporan'],
      'Bulan': r['Bulan'],
      'Produk': r['Nama Produk'],
      'Wilayah': r['Kategori Produk'],
      'Penjualan (Unit)': Number(r['Penjualan Harian']) || 0,
      'Target (Unit)': '',
      'Pendapatan (IDR)': Number(r['Total Penjualan (IDR)']) || 0,
      'Status': r['Catatan Status'] || '',
      'Keterangan': 'PJ: ' + (r['Karyawan Penanggung Jawab'] || '-') + ' | Stok: ' + (r['Jumlah Stok'] ?? 0) + ' | Harga: ' + (r['Harga Satuan (IDR)'] ?? 0),
      'Tanggal Laporan': '',
    },
  };
});

// Tambahkan kolom Sumber untuk data dari Sheet 3
return $input.all().map((item) => ({
  json: { ...item.json, 'Sumber': 'Sheet 3' },
}));

// Mode Append: item Sheet 1 berada di urutan awal, lalu Sheet 2
const jumlahSheet1 = $('Data Sheet 1').all().length;

return $input.all().map((item, index) => {
  const data = { ...item.json };
  delete data.row_number;
  data['Sumber'] = index < jumlahSheet1 ? 'Sheet 1' : 'Sheet 2';
  return { json: data };
});

// Agregasi data konsolidasi: total penjualan, total pendapatan, rata-rata performa bulanan
const rows = $('Gabung jadi 1').all().map((i) => i.json).filter((r) => r['ID Laporan']);

const urutanBulan = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const rupiah = (n) => 'Rp ' + Math.round(n).toLocaleString('id-ID');
const angka = (n) => Math.round(n).toLocaleString('id-ID');

let totalPenjualan = 0;
let totalPendapatan = 0;
let totalTarget = 0;
let penjualanBerTarget = 0;
const perBulan = {};

for (const r of rows) {
  const unit = num(r['Penjualan (Unit)']);
  const pendapatan = num(r['Pendapatan (IDR)']);
  const target = num(r['Target (Unit)']);
  totalPenjualan += unit;
  totalPendapatan += pendapatan;
  if (target > 0) { totalTarget += target; penjualanBerTarget += unit; }
  const b = String(r['Bulan'] || 'Tidak diketahui').trim();
  if (!perBulan[b]) perBulan[b] = { bulan: b, transaksi: 0, penjualan: 0, pendapatan: 0 };
  perBulan[b].transaksi += 1;
  perBulan[b].penjualan += unit;
  perBulan[b].pendapatan += pendapatan;
}

const daftarBulan = Object.values(perBulan).sort((a, b) => urutanBulan.indexOf(a.bulan) - urutanBulan.indexOf(b.bulan));
const jumlahBulan = daftarBulan.length || 1;
const rataPenjualan = totalPenjualan / jumlahBulan;
const rataPendapatan = totalPendapatan / jumlahBulan;
const pencapaian = totalTarget > 0 ? (penjualanBerTarget / totalTarget) * 100 : 0;
const terbaik = daftarBulan.reduce((best, m) => (!best || m.pendapatan > best.pendapatan ? m : best), null);

const tanggal = $now.setZone('Asia/Jakarta').toFormat('dd/MM/yyyy');
const periode = urutanBulan[$now.setZone('Asia/Jakarta').month - 1] + ' ' + $now.setZone('Asia/Jakarta').year;

const telegramText = [
  '<b>Laporan Performa Bulanan</b>',
  'Periode laporan: ' + periode + ' (dibuat ' + tanggal + ')',
  '',
  'Total Sales: <b>' + angka(totalPenjualan) + ' unit</b>',
  'Total Revenue: <b>' + rupiah(totalPendapatan) + '</b>',
  'Jumlah transaksi: ' + rows.length,
  'Rata-rata sales/bulan: ' + angka(rataPenjualan) + ' unit',
  'Rata-rata revenue/bulan: ' + rupiah(rataPendapatan),
  'Pencapaian target: ' + pencapaian.toFixed(1) + '%',
  'Bulan terbaik: ' + (terbaik ? terbaik.bulan + ' (' + rupiah(terbaik.pendapatan) + ')' : '-'),
].join('\n');

const barisTabel = daftarBulan.map((m) =>
  '<tr><td style="padding:6px;border:1px solid #ddd">' + m.bulan + '</td>' +
  '<td style="padding:6px;border:1px solid #ddd;text-align:right">' + m.transaksi + '</td>' +
  '<td style="padding:6px;border:1px solid #ddd;text-align:right">' + angka(m.penjualan) + '</td>' +
  '<td style="padding:6px;border:1px solid #ddd;text-align:right">' + rupiah(m.pendapatan) + '</td></tr>'
).join('');

const emailHtml =
  '<div style="font-family:Arial,sans-serif;color:#222">' +
  '<h2 style="color:#1a73e8">Laporan Performa Bulanan</h2>' +
  '<p>Periode laporan: <b>' + periode + '</b> &middot; Dibuat: ' + tanggal + '</p>' +
  '<table style="border-collapse:collapse;margin-bottom:16px">' +
  '<tr><td style="padding:6px">Total Sales</td><td style="padding:6px"><b>' + angka(totalPenjualan) + ' unit</b></td></tr>' +
  '<tr><td style="padding:6px">Total Revenue</td><td style="padding:6px"><b>' + rupiah(totalPendapatan) + '</b></td></tr>' +
  '<tr><td style="padding:6px">Jumlah Transaksi</td><td style="padding:6px">' + rows.length + '</td></tr>' +
  '<tr><td style="padding:6px">Rata-rata Sales / Bulan</td><td style="padding:6px">' + angka(rataPenjualan) + ' unit</td></tr>' +
  '<tr><td style="padding:6px">Rata-rata Revenue / Bulan</td><td style="padding:6px">' + rupiah(rataPendapatan) + '</td></tr>' +
  '<tr><td style="padding:6px">Pencapaian Target</td><td style="padding:6px">' + pencapaian.toFixed(1) + '%</td></tr>' +
  '<tr><td style="padding:6px">Bulan Terbaik</td><td style="padding:6px">' + (terbaik ? terbaik.bulan : '-') + '</td></tr>' +
  '</table>' +
  '<h3>Rincian per Bulan</h3>' +
  '<table style="border-collapse:collapse"><tr style="background:#f1f3f4">' +
  '<th style="padding:6px;border:1px solid #ddd">Bulan</th><th style="padding:6px;border:1px solid #ddd">Transaksi</th>' +
  '<th style="padding:6px;border:1px solid #ddd">Sales (Unit)</th><th style="padding:6px;border:1px solid #ddd">Revenue</th></tr>' +
  barisTabel + '</table>' +
  '<p style="margin-top:16px;font-size:12px;color:#666">Laporan ini dibuat otomatis oleh n8n.</p></div>';

return [{
  json: {
    tanggal_laporan: tanggal,
    periode,
    jumlah_transaksi: rows.length,
    total_penjualan: totalPenjualan,
    total_pendapatan: totalPendapatan,
    jumlah_bulan: daftarBulan.length,
    rata_penjualan_bulanan: Math.round(rataPenjualan),
    rata_pendapatan_bulanan: Math.round(rataPendapatan),
    pencapaian_target_persen: Number(pencapaian.toFixed(1)),
    bulan_terbaik: terbaik ? terbaik.bulan : '-',
    telegram_text: telegramText,
    email_html: emailHtml,
  },
}];
